#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Deploys Wherewolf: game server on Render, client on Vercel, LiveKit Cloud
# and ElevenLabs keys on the server only. See docs/deploy.md. Run from anywhere:
#   bash scripts/deploy-wizard.sh

cd "$(dirname "$0")/.."
# The deployed URLs are public, but kept out of the server's .env.
ENV_FILE=".env.deploy"
LOCAL_ENV=".env"
REPO="Oozak-ACY/Wherewolf"

# copy_to_clipboard VALUE puts VALUE on the clipboard without echoing it.
copy_to_clipboard() {
  if   command -v clip.exe >/dev/null 2>&1; then printf '%s' "$1" | clip.exe
  elif command -v pbcopy   >/dev/null 2>&1; then printf '%s' "$1" | pbcopy
  elif command -v wl-copy  >/dev/null 2>&1; then printf '%s' "$1" | wl-copy
  elif command -v xclip    >/dev/null 2>&1; then printf '%s' "$1" | xclip -selection clipboard
  else return 1; fi
}

# local_env KEY reads KEY from the server's local .env.
local_env() {
  [[ -f "$LOCAL_ENV" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$LOCAL_ENV" | tail -n1) || return 1
  line="${line%$'\r'}" # .env may have Windows line endings
  printf '%s' "${line#*=}"
}

# offer_value KEY WHERE URL: copies KEY's local value to the clipboard for
# pasting, or sends the human to WHERE (at URL) to copy it.
offer_value() {
  local key="$1" where="$2" url="$3" value
  value=$(local_env "$key" || true)
  if [[ -z "$value" ]]; then
    warn "$key is not in $LOCAL_ENV: copy it from $where"
    open_url "$url"
  elif copy_to_clipboard "$value"; then
    printf '  %s✓ copied%s %s to the clipboard\n' "$GREEN" "$RESET" "$key"
  else
    warn "no clipboard tool: copy $key from $LOCAL_ENV by hand"
  fi
  pause "Paste it into the $key field in Render, then press Enter"
}

TOTAL_STAGES=5

banner "Deploy Wherewolf online"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "Preflight: render.yaml is on GitHub"
say "Render reads the Blueprint (render.yaml) from $REPO on GitHub,"
say "so it has to be pushed to main before Render can see it."
git fetch -q origin main || warn "couldn't fetch origin; check your network"
if git cat-file -e origin/main:render.yaml 2>/dev/null; then
  printf '  %s✓ found%s render.yaml on origin/main\n' "$GREEN" "$RESET"
else
  warn "render.yaml is not on origin/main yet."
  step "Push it first:  git push origin main"
  confirm "Pushed it? Continue" || exit 1
fi
pause

# ── 2 ────────────────────────────────────────────────────────────────────
stage "Render: the game server"
say "Create the server from the Blueprint. Render's free plan sleeps when idle"
say "and takes ~1 min to wake up: that's expected."
open_url "https://dashboard.render.com/blueprints"
step "Sign in (or sign up) with GitHub."
step "Click 'New Blueprint Instance'."
step "Connect $REPO (grant Render access to the repo if asked)."
step "Name the Blueprint 'wherewolf'. Render reads render.yaml and lists"
step "the 'wherewolf-server' web service with four empty variables."
say ""
say "Fill them from your local .env, one at a time (never shown on screen):"
offer_value LIVEKIT_URL "LiveKit Cloud → Settings → API keys" "https://cloud.livekit.io"
offer_value LIVEKIT_API_KEY "LiveKit Cloud → Settings → API keys" "https://cloud.livekit.io"
offer_value LIVEKIT_API_SECRET "LiveKit Cloud → Settings → API keys" "https://cloud.livekit.io"
note "ELEVENLABS_API_KEY voices the Narrator's lines with names. Without it,"
note "the Table device says them with the browser's voice."
offer_value ELEVENLABS_API_KEY "ElevenLabs → Developers → API keys" "https://elevenlabs.io/app/developers/api-keys"
step "Click 'Deploy Blueprint' (or 'Apply')."
note "The first Rust build takes several minutes on the free plan."
step "Open the wherewolf-server service and wait until its status is 'Live'."
step "Copy its URL at the top of the page (like https://wherewolf-server.onrender.com)."
ask SERVER_URL "Paste the server URL:"
SERVER_URL="${SERVER_URL%/}"
write_env SERVER_URL "$SERVER_URL"

# ── 3 ────────────────────────────────────────────────────────────────────
stage "Check: the server answers"
say "Creating a Lobby on $SERVER_URL (up to ~1 min if it was asleep)…"
created=""
for attempt in 1 2 3; do
  if created=$(curl -fsS --max-time 90 -X POST "$SERVER_URL/api/lobbies" 2>/dev/null); then break; fi
  created=""
  note "attempt $attempt failed, retrying…"
done
if [[ "$created" == *'"code"'* ]]; then
  printf '  %s✓ server is up%s, it created a Lobby: %s\n' "$GREEN" "$RESET" "$created"
else
  warn "the server didn't answer. In Render, check the service's Logs tab:"
  note "'LIVEKIT_URL / … not set' means a variable is empty; a build error means the deploy failed."
  note "'ELEVENLABS_API_KEY not set' means the Narrator says names with the browser's voice."
  confirm "Continue anyway?" || exit 1
fi
pause

# ── 4 ────────────────────────────────────────────────────────────────────
stage "Vercel: the client"
say "Import the repo on Vercel, with the client folder as the project root."
open_url "https://vercel.com/new"
step "Sign in (or sign up) with GitHub, then Import $REPO."
step "Root Directory: click Edit and pick 'client'. Framework Preset: Vite."
step "Open 'Environment Variables' and add:"
say "      Key:   VITE_SERVER_URL"
say "      Value: $SERVER_URL"
copy_to_clipboard "$SERVER_URL" && note "(the value is on your clipboard)"
step "Click Deploy and wait for the confetti."
step "Copy the production domain (like https://wherewolf.vercel.app)."
ask CLIENT_URL "Paste the client URL:"
CLIENT_URL="${CLIENT_URL%/}"
write_env CLIENT_URL "$CLIENT_URL"
say ""
say "Checking the deployed client points at the server…"
bundle=$(curl -fsS --max-time 30 "$CLIENT_URL/" 2>/dev/null | grep -oE '/assets/[^"]+\.js' | head -n1 || true)
code=""
[[ -n "$bundle" ]] && code=$(curl -fsS --max-time 30 "$CLIENT_URL$bundle" 2>/dev/null || true)
if [[ "$code" == *"$SERVER_URL"* ]]; then
  printf '  %s✓ the client is built with%s VITE_SERVER_URL=%s\n' "$GREEN" "$RESET" "$SERVER_URL"
else
  warn "the deployed client doesn't mention $SERVER_URL."
  note "Check VITE_SERVER_URL in Vercel → Project → Settings → Environment Variables,"
  note "then Deployments → ⋯ → Redeploy (it's read at build time)."
fi
pause

# ── 5 ────────────────────────────────────────────────────────────────────
stage "Play on real phones"
say "The public link is:"
say ""
say "    ${BOLD}$CLIENT_URL${RESET}"
say ""
step "Send it to an iPhone and an Android phone, open it (Safari, Chrome)."
step "On one phone, create a Lobby; on the other, join it with the code or link."
step "Allow camera and microphone on both."
note "The first visit after a quiet spell can take ~1 min: the server is waking up."
if confirm "Do both phones see each other on video?"; then
  printf '  %s✓ Wherewolf is online%s\n' "$GREEN" "$RESET"
else
  SKIPPED+=("Phones: video not working. Check the Render logs and docs/deploy.md")
fi
pause

finish
say "Redeploying and rotating keys: docs/deploy.md"
printf '\n'
